// Main video player
const videoPlayer = document.getElementById('customization-video-player');

// Video container (useful for intersection observer)
const videoSection = document.getElementById('customization-video-section');

// Other useful IDs if needed
const customizationContainer = document.getElementById('customization-container-main');
const contentSection = document.getElementById('customization-content-section');
const startBtn = document.getElementById('customization-btn-start');
document.addEventListener('DOMContentLoaded', function() {
    const videoPlayer = document.getElementById('customization-video-player');
    
    if (!videoPlayer) return;
    
    // Your autoplay logic here
    const observerOptions = {
        root: null,
        rootMargin: '0px',
        threshold: 0.5
    };
    
    const videoObserver = new IntersectionObserver((entries) => {
        entries.forEach(entry => {
            if (entry.isIntersecting) {
                videoPlayer.play().catch(error => console.log('Autoplay failed:', error));
            } else {
                videoPlayer.pause();
            }
        });
    }, observerOptions);
    
    videoObserver.observe(videoPlayer);
});
